    private static HashSet<int> ParseGroups(string text){var values=text.Split([',',';',' '],StringSplitOptions.RemoveEmptyEntries).Select(s=>int.Parse(s,CultureInfo.InvariantCulture)).ToHashSet();if(values.Count>1000||values.Any(n=>n<=0||n>16777215))throw new IOException("Use positive comma-separated talkgroup IDs (maximum 1000).");return values;}
    private CapCarrier[] ValidateTrunkMaps(IEnumerable<TrunkMapRow> rows){var maps=rows.Where(r=>r.FrequencyMHz.Trim().Length>0).Select(r=>new CapCarrier(r.Lcn,ParseMHz(r.FrequencyMHz),r.Confirmed,r.Evidence,r.ColorCode)).ToArray();TrunkFollower.Validate(new("test","test",trunkMode.SelectedIndex==0?"P25":trunkMode.SelectedItem?.ToString()??"Capacity Plus",1,maps));return maps;}
    private static long ParseMHz(string text){if(!decimal.TryParse(text,NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out var mhz)||mhz<=0||mhz>6000||mhz*1000000!=decimal.Truncate(mhz*1000000))throw new IOException("Enter MHz with at most six decimal places.");return(long)(mhz*1000000);}
    private CapCarrier[] ReadTrunkMaps(){if(!trunkMapGrid.CommitEdit(DataGridEditingUnit.Cell,true)||!trunkMapGrid.CommitEdit(DataGridEditingUnit.Row,true))throw new IOException("Fix the highlighted map cell.");return ValidateTrunkMaps(trunkMaps);}
    private TrunkProfile ReadTrunkProfile()=>new(trunkId,trunkName.Text.Trim(),trunkMode.SelectedIndex==0?"P25":trunkMode.SelectedItem?.ToString()??"Capacity Plus",ParseMHz(trunkControl.Text),ReadTrunkMaps(),string.IsNullOrWhiteSpace(trunkNetwork.Text)?null:int.Parse(trunkNetwork.Text,CultureInfo.InvariantCulture),string.IsNullOrWhiteSpace(trunkSite.Text)?null:int.Parse(trunkSite.Text,CultureInfo.InvariantCulture));
    private void ApplyTrunkRules(){var allow=ParseGroups(trunkAllow.Text);var ignore=ParseGroups(trunkIgnore.Text);int? hold=string.IsNullOrWhiteSpace(trunkHold.Text)?null:int.Parse(trunkHold.Text,CultureInfo.InvariantCulture);if(hold is <=0 or >16777215)throw new IOException("Hold TG must be positive or blank.");double hang=double.Parse(trunkHang.Text,CultureInfo.InvariantCulture),maximum=double.Parse(trunkMaximum.Text,CultureInfo.InvariantCulture);if(!double.IsFinite(hang)||hang<1||hang>15||!double.IsFinite(maximum)||maximum<5||maximum>300)throw new IOException("Hang must be 1-15 s and maximum 5-300 s.");lock(trunkRadio.Sync){var m=trunkRadio.Model;m.RequireConfirmations=trunkConfirm.IsChecked==true;m.Allowed=allow;m.Ignored=ignore;m.Hold=hold;m.HangSeconds=hang;m.MaximumSeconds=maximum;if(m.Active is {} c&&(ignore.Contains(c.Talkgroup)||hold.HasValue&&hold!=c.Talkgroup||allow.Count>0&&!allow.Contains(c.Talkgroup)))m.End(DateTimeOffset.UtcNow,"Filter changed");}}
    private void SaveTrunkProfile(){var p=ReadTrunkProfile();TrunkFollower.Validate(p);ApplyTrunkRules();Dictionary<int,string> labels;lock(trunkRadio.Sync)labels=new(trunkRadio.Model.Labels);var next=new Dictionary<string,TrunkSaved>(trunkSaved){[p.Id]=new(p,trunkAllow.Text,trunkIgnore.Text,trunkHold.Text,labels,double.Parse(trunkHang.Text,CultureInfo.InvariantCulture),double.Parse(trunkMaximum.Text,CultureInfo.InvariantCulture),trunkRetune.IsChecked==true,trunkConfirm.IsChecked==true)};string temp=trunkSettings+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(next.Values.ToArray(),new JsonSerializerOptions{WriteIndented=true}));File.Move(temp,trunkSettings,true);trunkSaved.Clear();foreach(var pair in next)trunkSaved.Add(pair.Key,pair.Value);trunkProfiles.ItemsSource=next.Values.Select(v=>v.Profile).ToArray();}
    private void StartTrunk(){if(fleetProfile.Role=="Trunk voice")throw new IOException("This is a dedicated voice receiver. Start following on its control receiver, or change this workspace role to Independent.");if(!rfMode||receiver.IsReplay||receiver.SamplingMode!=0)throw new IOException("Start live quadrature SDR first; replay cannot control hardware.");StopActivity("Trunk following started");StopFolderScan("Trunk following started");var p=ReadTrunkProfile();if(!new ChannelSettings(p.ControlHz,"NFM",p.Protocol=="P25"?16000:12500).Fits(receiver.AppliedFrequency,receiver.AppliedBandwidth)&&trunkRetune.IsChecked!=true)throw new IOException("Control/rest is outside capture. Tune closer or explicitly allow hardware retunes.");SaveTrunkProfile();Aviation.Stop("Trunk following started");Television.StopLive("Trunk following started");HdRecordings.StopLive("Trunk following started");P25Packets.VoiceToggle.IsChecked=false;digitalMode.SelectedIndex=0;trunkGeneration++;trunkRetuneHz=0;trunkRadio.Start(p);trunkRadio.SuppressLocalVoice=fleetProfile.Role=="Trunk control";ApplyTrunkRules();if(new ChannelSettings(p.ControlHz,"NFM",16000).Fits(receiver.AppliedFrequency,receiver.AppliedBandwidth))receiver.SetChannel(new(p.ControlHz,"NFM",16000));engine.RetuneBoundary();}
    private void StopTrunk(bool restore){ReleaseFleetAssignments();long hz;lock(trunkRadio.Sync)hz=trunkRadio.Model.ControlHz;bool was=trunkRadio.Running;trunkGeneration++;trunkRadio.Stop();trunkAudioKey="";trunkAudioFrequency=0;if(was){engine.RetuneBoundary();if(restore&&rfMode&&!receiver.IsReplay&&hz>0)_=RetuneTrunk(hz,trunkGeneration,true);}}
    private async Task RetuneTrunk(long hz,long generation,bool returning=false){if(trunkRetuneBusy)return;trunkRetuneBusy=true;trunkRetuneHz=hz;trunkRetuneAt=DateTimeOffset.UtcNow;try{if(!rfMode||receiver.IsReplay)return;var ch=new ChannelSettings(hz,"NFM",16000);if(ch.Fits(receiver.AppliedFrequency,receiver.AppliedBandwidth)){if(returning)receiver.SetChannel(ch);return;}await receiver.Retune(hz,ch);}catch(Exception ex){if(generation==trunkGeneration){trunkRadio.Stop("Retune failed: "+ex.Message);Log("Trunk retune: "+ex.Message);}}finally{trunkRetuneBusy=false;}}
    private void SkipTrunkCall(){if(fleetOwner is {} owner&&trunkRadio.Model.Active is {} assigned){lock(owner.trunkRadio.Sync)owner.trunkRadio.Model.SkipGroup(assigned.Talkgroup,DateTimeOffset.UtcNow);EndFleetVoice("Skipped by user");}else lock(trunkRadio.Sync)trunkRadio.Model.Skip(DateTimeOffset.UtcNow);}
    private void IgnoreTrunkCall(){if(fleetOwner is {} owner&&trunkRadio.Model.Active is {} assigned){owner.trunkIgnore.Text=string.Join(',',ParseGroups(owner.trunkIgnore.Text).Append(assigned.Talkgroup).Distinct());owner.ApplyTrunkRules();EndFleetVoice("Talkgroup ignored on control receiver");return;}lock(trunkRadio.Sync){if(trunkRadio.Model.Active is {} c){trunkIgnore.Text=string.Join(',',ParseGroups(trunkIgnore.Text).Append(c.Talkgroup).Distinct());ApplyTrunkRules();trunkRadio.Model.End(DateTimeOffset.UtcNow,"Talkgroup ignored");}}}
    private static string DmrChannelTag(TrunkCall call)=>call.Protocol=="P25"?"":$" · slot {call.Slot}"+(call.ColorCode is int cc?$" · CC {cc}":"");
    private void AppendTrunkHistory(TrunkEvent row,bool session=false)
    {
        int index=0;while(index<trunkDiscoveries.Count&&trunkDiscoveries[index].Time>row.Time)index++;
        trunkDiscoveries.Insert(index,row);
        while(trunkDiscoveries.Count>500)trunkDiscoveries.RemoveAt(trunkDiscoveries.Count-1);
        if(session)Log($"Trunk {row.Kind}: {row.Receiver} ← {row.Control} · {row.Protocol} TG {row.Talkgroup} {row.Label} · {row.Frequency} MHz{(row.SlotDisplay.Length>0?$" · slot {row.SlotDisplay}":"")}{(row.ColorCodeDisplay.Length>0?$" · CC {row.ColorCodeDisplay}":"")} · radio {row.Radio?.ToString()??"unknown"} · NAC {(row.NacDisplay.Length>0?row.NacDisplay:"unknown")} · {row.Detail}");
    }
    private void TickTrunk()
    {
        foreach(var packet in trunkRadio.DrainAudio()){if(!fleetAudioReported&&fleetOwner is {} audioOwner&&fleetCall is {} audioCall){fleetAudioReported=true;RecordFleetEvent(audioOwner,audioCall with{Radio=packet.Radio??audioCall.Radio,ColorCode=packet.ColorCode??audioCall.ColorCode},"Decoded audio","Matching decoded voice delivered to listening output");}if(trunkAudioKey!=packet.Key){trunkAudioKey=packet.Key;trunkAudioFrequency=packet.Hz;engine.RetuneBoundary();}engine.FeedStereo(VoiceAudioGain.Apply(packet.Pcm,packet.Protocol=="P25"?voiceGainDb:digitalGainDb),true);}trunkRadio.Tick();
        foreach(var p in trunkRadio.DrainObservations()){P25Packets.Add(p);P25Systems.Observe(p);P25Activity.Observe(p);siteCollector?.Observe(p);}
        foreach(var r in trunkRadio.DrainDmr())ObserveDmrForSaving(r);
        foreach(var e in trunkRadio.DrainDiscovery())AppendTrunkHistory(e);
        TrunkCall? call;long control;bool running;TrunkEvent[] events;string state,voice;lock(trunkRadio.Sync){var m=trunkRadio.Model;call=m.Active;control=m.ControlHz;running=m.Running;state=m.Status;voice=trunkRadio.VoiceStatus;events=m.Events.ToArray();m.Events.Clear();}
        foreach(var e in events){var row=e with{Receiver=fleetProfile.Name,Control=fleetOwner?.fleetProfile.Name??"",Label=e.Talkgroup is int tg?trunkRadio.Model.Labels.GetValueOrDefault(tg,""):"",Radio=e.Radio??(e.Talkgroup==fleetCall?.Talkgroup?fleetCall?.Radio:null),Nac=e.Nac??(e.Talkgroup==fleetCall?.Talkgroup?fleetCall?.Nac:null)};AppendTrunkHistory(row,e.Kind=="Call end");if(e.Kind=="Call end"&&fleetOwner is {} owner)owner.AppendTrunkHistory(row,true);}
        string key=call==null?"":$"{call.Protocol}:{call.Hz}:{call.Slot}:{call.Talkgroup}:{call.First.UtcTicks}";if(call==null&&trunkAudioKey.Length>0){trunkAudioKey="";trunkAudioFrequency=control;engine.RetuneBoundary();}
        bool dedicatedVoice=fleetProfile.Role=="Trunk voice";if(trunkSetup!=null)trunkSetup.Visibility=dedicatedVoice?Visibility.Collapsed:Visibility.Visible;if(trunkVoiceActions!=null)trunkVoiceActions.Visibility=dedicatedVoice?Visibility.Visible:Visibility.Collapsed;
        trunkNetwork.IsEnabled=trunkSite.IsEnabled=trunkConfirm.IsEnabled=!running;trunkMapGrid.IsReadOnly=running;trunkRetune.IsEnabled=trunkMode.IsEnabled=trunkControl.IsEnabled=trunkProfiles.IsEnabled=!running;
        if(DateTimeOffset.UtcNow-trunkUiAt>TimeSpan.FromMilliseconds(250)){trunkUiAt=DateTimeOffset.UtcNow;string label="";lock(trunkRadio.Sync)if(call!=null)label=trunkRadio.Model.Labels.GetValueOrDefault(call.Talkgroup,"");trunkStatus.Text=FleetControlActive?$"Monitoring control · {fleetLeases.Count} voice receiver assignment(s)":state+(call is {} a?$" | TG {a.Talkgroup} {label} | radio {a.Radio?.ToString()??"unknown"} | {a.Hz/1e6:F6} MHz {(a.Protocol=="P25"?"":$"| slot {a.Slot}")}":"");trunkVoiceStatus.Text=$"{(fleetPaused?"Voice pool paused | ":"")}{(FleetControlActive?$"Voice receivers assigned: {fleetLeases.Count} | ":"")}{(fleetOwner!=null?"Voice tuned":"Control/rest")} {control/1e6:F6} MHz | {trunkRadio.ReceiverStatus} | {voice} | dropped {trunkRadio.Dropped} | decoded audio samples {trunkRadio.AudioFrames}";
         string summary= fleetOwner!=null&&(call??fleetCall) is {} fc?$"{(fleetVoiceBusy?"Assigning":"Following")} {fc.Protocol} · TG {fc.Talkgroup} {fleetCallLabel} · {fc.Hz/1e6:F6} MHz{DmrChannelTag(fc)} · control {fleetOwner.fleetProfile.Name}":FleetControlActive?string.Join("   |   ",fleetLeases.Keys.Where(w=>w.fleetCall!=null).Select(w=>$"{w.fleetProfile.Name}: {(w.fleetVoiceBusy?"assigning":"tuned")} TG {w.fleetCall!.Talkgroup} {w.fleetCallLabel} · {w.fleetCall.Hz/1e6:F6} MHz{DmrChannelTag(w.fleetCall)}")):"";
